import time
from functools import wraps

def timed(f):
    @wraps(f)
    def wrapper(*args, **kwargs):
        t0 = time.perf_counter()
        try:
            return f(*args, **kwargs)
        finally:
            print(f'{f.__name__} took {time.perf_counter()-t0:.6f}s')
    return wrapper

@timed
def slow_add(a, b):
    'slow add'
    time.sleep(0.01)
    return a + b

print(slow_add(1, 2), slow_add.__name__)

def make_checker(target):
    # 工厂函数：捕获 target，返回一个判断配对的闭包
    def check(seen, v):
        return (target - v) in seen
    return check

def two_sum(nums, target):
    check = make_checker(target)   # target 被闭包捕获，调用时无需重复传参
    seen = {}
    for i, v in enumerate(nums):
        if check(seen, v):
            return [seen[target - v], i]
        seen[v] = i
    return []

print(two_sum([2, 7, 11, 15], 9))  # [0, 1]
